dockerStartCmd:
set -uo pipefail
log(){ echo "[exp48 $(date +%H:%M:%S)] $*"; }
command -v git >/dev/null || { apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq git; }
cd /workspace && rm -rf repo && git clone -q --depth 1 https://github.com/terrafying/ai-torture-chamber.git repo && cd repo || exit 1
mkdir -p runs/exp48
# serve results from the start, so progress is visible while it runs
(cd runs/exp48 && python -m http.server 8000 >/dev/null 2>&1 &)
log "deps"
pip install -q --no-cache-dir 'torch==2.8.0' --index-url https://download.pytorch.org/whl/cu128 > runs/exp48/pip.log 2>&1
pip install -q --no-cache-dir 'transformers==5.17.0' numpy accelerate bitsandbytes mistral-common >> runs/exp48/pip.log 2>&1
# the base image's torchvision/torchaudio are built for torch 2.4 and break
# transformers' lazy model imports ("Could not import module Qwen3ForCausalLM")
pip uninstall -y -q torchvision torchaudio >> runs/exp48/pip.log 2>&1
python -c "import torch; assert torch.cuda.is_available(); print(torch.__version__, torch.cuda.get_device_name())" > runs/exp48/env.txt 2>&1 || { log "no CUDA"; sleep infinity; }
python -c "import transformers.models.qwen3.modeling_qwen3 as m; print('qwen3 import ok', m.__name__)" >> runs/exp48/env.txt 2>&1 || { log "import broken"; touch runs/exp48/FAILED; sleep infinity; }
export HF_HOME=/workspace/hf
n=Mistral-Small-3.2-24B-Instruct-2506; log "$n"; python exp48_emotion_binding.py --smoke --device cuda --model mistralai/Mistral-Small-3.2-24B-Instruct-2506 > runs/exp48/$n.smoke.log 2>&1 && python exp48_emotion_binding.py --device cuda --model mistralai/Mistral-Small-3.2-24B-Instruct-2506 > runs/exp48/$n.log 2>&1 || { log "$n FAILED"; touch runs/exp48/FAILED_$n; }
n=Qwen3-32B; log "$n"; python exp48_emotion_binding.py --smoke --device cuda --model Qwen/Qwen3-32B > runs/exp48/$n.smoke.log 2>&1 && python exp48_emotion_binding.py --device cuda --model Qwen/Qwen3-32B > runs/exp48/$n.log 2>&1 || { log "$n FAILED"; touch runs/exp48/FAILED_$n; }
n=Hermes-3-Llama-3.1-70B-bnb-4bit; log "$n"; python exp48_emotion_binding.py --smoke --device cuda --model unsloth/Hermes-3-Llama-3.1-70B-bnb-4bit > runs/exp48/$n.smoke.log 2>&1 && python exp48_emotion_binding.py --device cuda --model unsloth/Hermes-3-Llama-3.1-70B-bnb-4bit > runs/exp48/$n.log 2>&1 || { log "$n FAILED"; touch runs/exp48/FAILED_$n; }
log "done"; touch runs/exp48/ALL_DONE
sleep infinity
